      backup_text =
        "# Garden of Life #\n\n\
         # A night garden that grows by Conway's rules: click cells to sow. \
         The grid #\n\
         # is a clickable Table, and Every drives generations while it is \
         running. #\n\n\
         type Cell = + Dead + Alive in\n\n\
         type Grid = (\n\
         cells = [Cell],\n\
         width = Int,\n\
         height = Int\n\
         ) in\n\n\
         type Model = (\n\
         grid = Grid,\n\
         running = Bool,\n\
         generation = Int\n\
         ) in\n\n\
         type Action =\n\
         + ToggleCell(Int)\n\
         + Step\n\
         + ToggleRunning\n\
         + Reset\n\
         + Glider\n\
         in\n\n\
         # Grid operations #\n\
         let makeGrid(w: Int, h: Int) : Grid =\n\
         (cells = map(range(0, w * h - 1), fun _ -> Dead), width = w, height = \
         h)\n\
         in\n\n\
         let toIndex(g: Grid, x: Int, y: Int) : Int =\n\
         y * g.width + x\n\
         in\n\n\
         let inBounds(g: Grid, x: Int, y: Int) : Bool =\n\
         x >= 0 && x < g.width && y >= 0 && y < g.height\n\
         in\n\n\
         let getCell(g: Grid, x: Int, y: Int) : Cell =\n\
         if inBounds(g, x, y) then nth(g.cells, toIndex(g, x, y)) else Dead\n\
         in\n\n\
         let setCell(g: Grid, x: Int, y: Int, cell: Cell) : Grid =\n\
         let idx = toIndex(g, x, y) in\n\
         (cells = mapi(g.cells, fun (i, c) -> if i == idx then cell else c),\n\
         width = g.width, height = g.height)\n\
         in\n\n\
         let countNeighbors(g: Grid, x: Int, y: Int) : Int =\n\
         length(filter([\n\
         getCell(g, x - 1, y - 1), getCell(g, x, y - 1), getCell(g, x + 1, y - \
         1),\n\
         getCell(g, x - 1, y),                             getCell(g, x + 1, y),\n\
         getCell(g, x - 1, y + 1), getCell(g, x, y + 1), getCell(g, x + 1, y + \
         1)\n\
         ], fun c -> c == Alive))\n\
         in\n\n\
         let nextCellState(current: Cell, neighbors: Int) : Cell =\n\
         case current\n\
         | Alive => if neighbors == 2 || neighbors == 3 then Alive else Dead\n\
         | Dead => if neighbors == 3 then Alive else Dead\n\
         end\n\
         in\n\n\
         let stepGrid(g: Grid) : Grid =\n\
         let newCells = mapi(g.cells, fun (idx, _) ->\n\
         let x = int_mod(idx, g.width) in\n\
         let y = idx / g.width in\n\
         nextCellState(getCell(g, x, y), countNeighbors(g, x, y))\n\
         ) in\n\
         (cells = newCells, width = g.width, height = g.height)\n\
         in\n\n\
         let setAlive(g: Grid, coords: [(Int, Int)]) : Grid =\n\
         fold_left(coords, (fun (grid, xy) ->\n\
         let (x, y) = xy in setCell(grid, x, y, Alive)\n\
         ), g)\n\
         in\n\n\
         let countAlive(g: Grid) : Int =\n\
         length(filter(g.cells, fun c -> c == Alive))\n\
         in\n\n\
         # Glider pattern at (1,1) #\n\
         let placeGlider(grid: Grid) : Grid =\n\
         setAlive(grid, [(2, 1), (3, 2), (1, 3), (2, 3), (3, 3)])\n\
         in\n\n\
         let gridSize: Int = 8 in\n\n\
         let init: Model = (\n\
         grid = makeGrid(gridSize, gridSize),\n\
         running = false,\n\
         generation = 0\n\
         ) in\n\n\
         # Only the grid changes on most actions, so name that once #\n\
         let withGrid(model: Model, grid: Grid): Model =\n\
         (\n\
         grid = grid,\n\
         running = model.running,\n\
         generation = model.generation\n\
         )\n\
         in\n\n\
         let toggleAt(grid: Grid, idx: Int): Grid =\n\
         let flipped =\n\
         case nth(grid.cells, idx)\n\
         | Alive => Dead\n\
         | Dead => Alive\n\
         end\n\
         in\n\
         (\n\
         cells = mapi(grid.cells, fun (i, c) -> if i == idx then flipped else \
         c),\n\
         width = grid.width,\n\
         height = grid.height\n\
         )\n\
         in\n\n\
         let update(model: Model, action: Action): Model =\n\
         case action\n\
         | ToggleCell(idx) => withGrid(model, toggleAt(model.grid, idx))\n\
         | Step =>\n\
         (\n\
         grid = stepGrid(model.grid),\n\
         running = model.running,\n\
         generation = model.generation + 1\n\
         )\n\
         | ToggleRunning =>\n\
         (\n\
         grid = model.grid,\n\
         running = !model.running,\n\
         generation = model.generation\n\
         )\n\
         | Reset => init\n\
         | Glider => withGrid(model, placeGlider(model.grid))\n\
         end\n\
         in\n\n\
         let cellColor(cell: Cell): String =\n\
         case cell | Alive => \"var(--G0)\" | Dead => \"var(--T1)\" end\n\
         in\n\n\
         # Every control is the same neutral button; only Run/Pause takes an \
         accent, #\n\
         # since it is the one that changes what the grid is doing #\n\
         let control(label: String, action: Action, accent: Bool): HTML =\n\
         Button(\n\
         [OnClick(action),\n\
         Style([(\"padding\", \"0.35em 0.6em\"), (\"border-radius\", \"3px\"),\n\
         (\"cursor\", \"pointer\"), (\"font-family\", \"inherit\"), \
         (\"font-size\", \"0.85em\"),\n\
         (\"background\", if accent then \"var(--G0)\" else \"var(--T1)\"),\n\
         (\"color\", if accent then \"var(--SAND)\" else \"var(--STONE)\"),\n\
         (\"border\", if accent then \"1px solid var(--G0)\" else \"1px solid \
         var(--BR1)\")])],\n\
         [Text(label)]\n\
         )\n\
         in\n\n\
         let view(model: Model): HTML =\n\
         Div(\n\
         [Style([(\"max-width\", \"320px\"), (\"margin\", \"0 auto\"), \
         (\"text-align\", \"center\"),\n\
         (\"font-family\", \"var(--code-font)\"), (\"font-size\", \"0.85em\"),\n\
         (\"background\", \"var(--SAND)\"), (\"color\", \"var(--STONE)\"),\n\
         (\"border\", \"1px solid var(--BR1)\"), (\"border-radius\", \"0.4em\"),\n\
         (\"overflow\", \"hidden\")])],\n\
         [\n\
         Div(\n\
         [Style([(\"padding\", \"0.9em 1em 0.8em\")])],\n\
         [\n\
         Div([Style([(\"font-size\", \"1.2em\"), (\"font-weight\", \"bold\"), \
         (\"color\", \"var(--BR4)\")])],\n\
         [Text(\"\240\159\140\177 Garden of Life\")]),\n\
         Div([Style([(\"font-size\", \"0.75em\"), (\"color\", \"var(--BR3)\"), \
         (\"margin-top\", \"0.3em\")])],\n\
         [Text(\"Sow a cell; the grove spreads by Conway's rules\")])\n\
         ]\n\
         ),\n\
         Div(\n\
         [Style([(\"padding\", \"0.7em 1em\"), (\"background\", \"var(--T2)\"),\n\
         (\"border-top\", \"1px solid var(--BR1)\"),\n\
         (\"border-bottom\", \"1px solid var(--BR1)\")])],\n\
         [\n\
         Div([Style([(\"font-size\", \"0.75em\"), (\"color\", \"var(--BR3)\"),\n\
         (\"text-transform\", \"uppercase\")])],\n\
         [Text(\"Generation\")]),\n\
         Div([Style([(\"font-size\", \"1.5em\"), (\"font-weight\", \"bold\"), \
         (\"color\", \"var(--BR4)\")])],\n\
         [Text(string_of_int(model.generation))])\n\
         ]\n\
         ),\n\
         Div(\n\
         [Style([(\"padding\", \"0.7em 1em\")])],\n\
         [\n\
         # Grid using Table #\n\
         Table(\n\
         [Style([(\"border-collapse\", \"collapse\"), (\"margin\", \"0 \
         auto\")])],\n\
         map(range(0, model.grid.height - 1), fun y ->\n\
         Tr([], map(range(0, model.grid.width - 1), fun x ->\n\
         let idx = y * model.grid.width + x in\n\
         let cell = nth(model.grid.cells, idx) in\n\
         Td(\n\
         [\n\
         OnClick(ToggleCell(idx)),\n\
         Style([\n\
         (\"width\", \"20px\"), (\"height\", \"20px\"),\n\
         (\"border\", \"1px solid var(--BR1)\"),\n\
         (\"cursor\", \"pointer\"),\n\
         (\"background\", cellColor(cell)),\n\
         (\"transition\", \"background 0.1s\")\n\
         ])\n\
         ],\n\
         []\n\
         )\n\
         ))\n\
         )\n\
         ),\n\
         Div(\n\
         [Style([(\"display\", \"grid\"), (\"grid-template-columns\", \"1fr \
         1fr\"),\n\
         (\"gap\", \"0.4em\"), (\"margin-top\", \"0.7em\")])],\n\
         [\n\
         control(if model.running then \"Pause\" else \"Run\", ToggleRunning, \
         !model.running),\n\
         control(\"Step\", Step, false),\n\
         control(\"Glider\", Glider, false),\n\
         control(\"Reset\", Reset, false)\n\
         ]\n\
         )\n\
         ]\n\
         )\n\
         ]\n\
         )\n\
         in\n\n\
         let subs(model: Model): Sub =\n\
         if model.running then Every(400.0, fun _ts -> Step) else SubNone\n\
         in\n\n\
         # With (model, action) order, `update` already has fold_left's shape #\n\
         let do_actions(model: Model, actions: [Action]): Model =\n\
         fold_left(actions, update, model)\n\
         in\n\n\
         # Tests #\n\n\
         # Kept small on purpose: these run every time the slide loads, and \
         stepping #\n\
         # the full 8-by-8 grid costs far more than stepping a 3-by-3 one. #\n\n\
         hint \"a cell with too few neighbors dies, one with three is born\"\n\
         test\n\
         let g = setAlive(makeGrid(3, 3), [(0, 0), (1, 0), (0, 1)]) in\n\
         let g2 = stepGrid(g) in\n\
         getCell(g2, 1, 1) == Alive\n\
         && getCell(g2, 0, 0) == Alive\n\
         && getCell(g2, 2, 2) == Dead\n\
         end;\n\n\
         hint \"a blinker flips between horizontal and vertical\"\n\
         test\n\
         let g = setAlive(makeGrid(3, 3), [(0, 1), (1, 1), (2, 1)]) in\n\
         let g2 = stepGrid(g) in\n\
         getCell(g2, 1, 0) == Alive\n\
         && getCell(g2, 1, 1) == Alive\n\
         && getCell(g2, 1, 2) == Alive\n\
         && getCell(g2, 0, 1) == Dead\n\
         && getCell(g2, 2, 1) == Dead\n\
         end;\n\n\
         hint \"clicking sows a cell, and the glider button sows five more\"\n\
         test\n\
         let m = do_actions(init, [ToggleCell(0), Glider]) in\n\
         nth(m.grid.cells, 0) == Alive && countAlive(m.grid) == 6\n\
         end;\n\n\
         # Nothing here issues a command, so `update` returns a bare Model and \
         is #\n\
         # lifted into the (Model, Cmd) shape the app tuple expects. #\n\n\
         let noCmd(f: (Model, Action) -> Model): (Model, Action) -> (Model, \
         Cmd) =\n\
         fun (model, action) -> (f(model, action), CmdNone)\n\
         in\n\n\
         ^^html((init, noCmd(update), view, subs))\n";
      refractors = "()";
    } )
